def convex_hull(points, xtol=1e-8, ytol=1e-8):
    """Compute the convex hull of a set of 2D points."""
    points = list(tuple(p) for p in points)
    points = sorted(points)
    def cross(o, a, b, c):
        return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])

    def cross_oa_ba(ob, ab):
        return ob[0] * ab[1] - ob[1] * ab[0]

    def cross2(a, b, c):
        return (b[0]-a[0]) * (c[1]-b[1]) - (b[1]-a[1]) * (c[0]-b[0])

    def dist(a,b):
        return (a[0]-b[0])**2 + **(a[1]-b[1])

    x, y = zip(*points)
    m_x = min(x)
    m_y = min(y)
    min_d = m_y-m_x
    for p0 in points:
        o1 = cross_oa_ba((m_x,0), (m_y,0))  
        o2 = cross_oa_ba((m_y,0), (m_x,0))
        if cross2(o1, o2, p0) >= 0:
            min_d = min(min_d, dist(p0, (m_x, m_y)))
        for p1 in points:
